draw(graph(x->a*log(x-h,3)+k, 3.1, 15),blue); // f(x)
draw(graph(x->x-3, 0, 15),dotted); // asymptote x=3
draw((0,5)--(15,5),dashed); // y=k
dot((4,5)); label("(4, 5)", (4,5), SE);
dot((12,7)); label("(12, 7)", (12,7), SE);
label("$f(x) = a \log_3(x-h) + k$", (14,9), NE);
label("$x=3$", (3,8), NE);
xaxis(-1, 15, Ticks());
yaxis(-5, 10, Ticks());
